-- Minimal production-shaped empty baseline before immutable migrations 036-039.
-- Synthetic schema only; no production dump or secret-bearing value is used.
DROP DATABASE IF EXISTS canonical_identity_test;
CREATE DATABASE canonical_identity_test CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE canonical_identity_test;

CREATE TABLE _migration_history (
    filename VARCHAR(255) CHARACTER SET ascii NOT NULL PRIMARY KEY,
    sha256 CHAR(64) CHARACTER SET ascii NOT NULL,
    applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE WEO_MEMBER (
    USR_SEQ INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    USR_ID VARCHAR(191) NULL,
    USR_EMAIL VARCHAR(255) NULL,
    USR_PWD VARCHAR(255) NULL,
    USR_NAME VARCHAR(100) NULL,
    USR_PHONE VARCHAR(30) NULL,
    USR_FN VARCHAR(20) NULL,
    USR_DEPT VARCHAR(100) NULL,
    USR_STATUS VARCHAR(3) NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4;

CREATE TABLE WEO_MEMBER_SOCIAL (
    NMS_SEQ INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    USR_SEQ INT NOT NULL,
    NMS_GATE VARCHAR(20) NOT NULL,
    NMS_ID VARCHAR(191) NOT NULL,
    NMS_EMAIL VARCHAR(255) NULL,
    NMS_STATUS VARCHAR(20) NULL DEFAULT 'ACTIVE',
    NMS_EMAIL_ENABLED ENUM('Y','N') NOT NULL DEFAULT 'Y',
    NMS_NAME VARCHAR(100) NULL,
    REG_DATE DATETIME NULL,
    INDEX IDX_USR_SEQ (USR_SEQ)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4;

CREATE TABLE ALUMNI_MOBILE_REFRESH_TOKEN (
    MRT_JTI VARCHAR(64) NOT NULL PRIMARY KEY,
    USR_SEQ INT NOT NULL,
    MRT_SID VARCHAR(64) NOT NULL,
    EXPIRES_AT DATETIME NOT NULL,
    CREATED_AT DATETIME NOT NULL,
    MRT_REVOKED_AT DATETIME NULL,
    INDEX IDX_MRT_USR (USR_SEQ),
    INDEX IDX_MRT_EXPIRES (EXPIRES_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
